function validate([fronts, backs]) {
  if (!Array.isArray(fronts) || fronts.length < 1 || fronts.length > 1000) return 'fronts needs 1 to 1000 values.';
  if (!Array.isArray(backs) || backs.length !== fronts.length) return 'backs must have the same length as fronts.';
  if ([...fronts, ...backs].some(v => !Number.isInteger(v) || v < 1 || v > 2000)) return 'Every card value is a whole number from 1 to 2000.';
  return null;
}

