function flipgame(fronts, backs) {
  // Try every way of turning the cards and read off the good integers of each.
  const n = fronts.length, up = [], down = [];
  let answer = 0;
  const choose = i => {
    if (i === n) {
      const shown = new Set(up);
      for (const v of down) if (!shown.has(v) && (answer === 0 || v < answer)) answer = v;
      return;
    }
    up.push(fronts[i]); down.push(backs[i]);
    choose(i + 1);
    up.pop(); down.pop();
    up.push(backs[i]); down.push(fronts[i]);
    choose(i + 1);
    up.pop(); down.pop();
  };
  choose(0);
  return answer;
}

