function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const cards = [];
  if (size === 'small') {
    const n = pick(1, 10), top = pick(2, 8), doubles = rand() * 0.6;
    for (let i = 0; i < n; i++) {
      const a = pick(1, top);
      cards.push([a, rand() < doubles ? a : pick(1, top)]);
    }
  } else {
    // Block most of the small values with same-on-both-sides cards so the answer is not simply 1.
    const n = 1000, blockedUpTo = pick(1, 500);
    for (let v = 1; v <= blockedUpTo && cards.length < n; v++) if (rand() < 0.9) cards.push([v, v]);
    const allDoubles = rand() < 0.15;
    while (cards.length < n) {
      if (allDoubles) { const v = pick(1, blockedUpTo); cards.push([v, v]); }
      else cards.push([pick(1, 2000), pick(1, 2000)]);
    }
    for (let i = cards.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [cards[i], cards[j]] = [cards[j], cards[i]]; }
  }
  for (const card of cards) if (rand() < 0.5) card.reverse();
  return [cards.map(c => c[0]), cards.map(c => c[1])];
}
